import { Component, computed, input } from '@angular/core';

/** hrm-progress-cell — thanh tiến độ mảnh (6px) + % trong ô bảng. Tự vẽ bằng token (không lib),
 *  nên bám Light/Dark. Màu theo `color`; giá trị hiển thị bên phải (tùy chọn). */
@Component({
  selector: 'hrm-progress-cell',
  template: `
    @if (label()) { <span class="pc-label">{{ label() }}</span> }
    <span class="pc-track"><span class="pc-fill" [style.width.%]="pct()"></span></span>
    @if (showValue()) { <span class="pc-val">{{ display() }}</span> }
  `,
  host: { class: 'hrm-progress-cell', '[attr.data-color]': 'color()' },
  styles: [`
:host { display: inline-flex; align-items: center; gap: 8px; min-width: 120px; width: 100%;
  --_c: var(--primary-base); }
:host([data-color='blue'])  { --_c: var(--blue-600); }
:host([data-color='green']) { --_c: var(--success-base); }
:host([data-color='amber']) { --_c: var(--warning-base); }
:host([data-color='red'])   { --_c: var(--error-base); }
.pc-label { font-size: var(--fs-12); color: var(--text-sub); flex: none; }
.pc-track { position: relative; flex: 1; height: 6px; border-radius: var(--radius-full);
  background: var(--track); overflow: hidden; }
.pc-fill { position: absolute; inset: 0 auto 0 0; height: 100%; border-radius: var(--radius-full);
  background: var(--_c); transition: width var(--duration-slow) var(--ease-out); }
.pc-val { flex: none; min-width: 34px; text-align: right; font-size: var(--fs-12); font-weight: 500;
  color: var(--text-body); font-variant-numeric: tabular-nums; }
  `],
})
export class HrmProgressCell {
  readonly value = input(0);
  readonly max = input(100);
  readonly color = input<'primary' | 'blue' | 'green' | 'amber' | 'red'>('primary');
  readonly showValue = input(true);
  /** Nhãn ngắn trước thanh (VD "Bộ nhớ"). */
  readonly label = input('');
  /** Hậu tố giá trị; '%' mặc định. */
  readonly suffix = input('%');

  protected readonly pct = computed(() => {
    const m = this.max() || 100;
    return Math.max(0, Math.min(100, (this.value() / m) * 100));
  });
  protected readonly display = computed(() => `${Math.round(this.pct())}${this.suffix()}`);
}
